#!/usr/bin/env bash
# AUTO-GENERATED by scripts/gen_launcher.sh from runbooks/.../VLLM-23-WeiboAI_VibeThinker-3B_final.sh.
# Canonical, fully-validated vLLM serve config (passed all three gates). Self-contained:
# pinned image digest + model + revision + flags inlined. Serves on http://HOST:PORT/v1.
#   ./VLLM-23-WeiboAI_VibeThinker-3B.sh            # serve in the foreground (Ctrl-C stops + removes the container)
